package ru.itmo.ui

import com.intellij.ui.scale.JBUIScale
import java.awt.Graphics2D
import java.awt.RenderingHints
import java.awt.image.BufferedImage
import java.util.Properties
import java.util.concurrent.ConcurrentHashMap
import javax.imageio.ImageIO

/**
 * Sprite-sheet animation generated by `tools/sticker_to_sprites.py`.
 *
 * Resources live in `/duck/<size>/<state>.png`, `<state>@2x.png` and `<state>.properties`.
 * Frames are laid out left-to-right, top-to-bottom, `columns` frames per row.
 */
class DuckAnimation private constructor(
    private val sheet: BufferedImage,
    private val sheet2x: BufferedImage,
    val frameCount: Int,
    val fps: Int,
    /** Frame size in logical (unscaled) pixels. */
    val frameWidth: Int,
    val frameHeight: Int,
    private val columns: Int,
) {
    /** Paints [frame] with its top-left corner at ([x], [y]), sized `JBUI.scale(frameWidth) x JBUI.scale(frameHeight)`. */
    fun paintFrame(g: Graphics2D, frame: Int, x: Int, y: Int) =
        paintFrame(g, frame, x, y, JBUIScale.scale(frameWidth), JBUIScale.scale(frameHeight))

    /** Paints [frame] scaled to [width] x [height] pixels (in the coordinate space of [g]) with its top-left at ([x], [y]). */
    fun paintFrame(g: Graphics2D, frame: Int, x: Int, y: Int, width: Int, height: Int) {
        val useHiDpi = JBUIScale.sysScale(g) * JBUIScale.scale(1f) > 1.01f
        val image = if (useHiDpi) sheet2x else sheet
        val factor = if (useHiDpi) 2 else 1
        val index = Math.floorMod(frame, frameCount)
        val sx = (index % columns) * frameWidth * factor
        val sy = (index / columns) * frameHeight * factor

        val g2 = g.create() as Graphics2D
        try {
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR)
            g2.drawImage(
                image,
                x,
                y,
                x + width,
                y + height,
                sx,
                sy,
                sx + frameWidth * factor,
                sy + frameHeight * factor,
                null
            )
        } finally {
            g2.dispose()
        }
    }

    companion object {
        private val cache = ConcurrentHashMap<String, DuckAnimation>()

        /** @param state lowercase state name, e.g. `idle`; @param size sprite size directory, e.g. `status` */
        fun load(state: String, size: String = "status"): DuckAnimation =
            cache.computeIfAbsent("$size/$state") { _ ->
                val path = "$size/$state"
                val properties = Properties().apply {
                    resource("/duck/$path/animation.properties").use {
                        load(it)
                    }
                }
                DuckAnimation(
                    sheet = resource("/duck/$path/animation.png").use { ImageIO.read(it) },
                    sheet2x = resource("/duck/$path/animation@2x.png").use { ImageIO.read(it) },
                    frameCount = properties.getProperty("frameCount").toInt(),
                    fps = properties.getProperty("fps").toInt(),
                    frameWidth = properties.getProperty("frameWidth").toInt(),
                    frameHeight = properties.getProperty("frameHeight").toInt(),
                    columns = properties.getProperty("columns").toInt(),
                )
            }

        private fun resource(path: String) =
            DuckAnimation::class.java.getResourceAsStream(path) ?: error("Duck animation resource not found: $path")
    }
}
